'use client';

/**
 * <RoxyNumerologyCard data={...} />: Numerology card for life path, expression, soul urge, personality, personal year, or full chart.
 *
 * You own this file. Customize freely. The component is re-exported from
 * @roxyapi/ui-react and stays in sync with the published package.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/numerology-card/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   const { data } = await roxy.numerology.calculateLifePath({ body: await req.json() });
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyNumerologyCard as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyNumerologyCardProps = ComponentProps<typeof Element>;

export function RoxyNumerologyCard(props: RoxyNumerologyCardProps) {
	return <Element {...props} />;
}

export default RoxyNumerologyCard;
